// Compile with the release's actual Sources/Core.swift. No real home directory or feeds are read.
import Foundation
@main struct Benchmark {static func main() throws {
let clock=Dates.parse("2026-11-20T12:00:00Z")!.date, w=HorizonWindow(months:3,now:clock), enabled=Set(SourceKind.allCases)
let topics=["Asterline","Bellwater","Coralwick","Dunhaven"]
let questions=["For Asterline, what carton count and pickup day does the latest dispatch note specify?","For Bellwater, what finish and quantity does the proof request specify?","For Coralwick, how many items are permitted and when should the team revisit that decision?","For Dunhaven, do the records establish that the agreement was signed? Identify what is actually documented."]
let labels=["dispatch note: 48 cartons; pickup Thursday","proof request: satin finish; quantity 125","original exception: cap 17 units; review February","draft agreement sent for legal review; signature not confirmed"]
let counts=[48,2,30,9];let ordinary=["production scheduling notes for the weekly operations review","artwork checklist and internal layout handover","follow-up about sample routing and packaging","fulfillment worksheet for regional planning","progress review and outstanding documentation","supplier correspondence and shipment planning","archived revision of the monthly tracking sheet"]
var result=[[String:Any]]();for i in topics.indices{let name=topics[i],count=counts[i];var rows=[Evidence]();for j in 0..<count{let t=RecordType.allCases[j%3];let isFact=j==(i==2 ? count-1 : 0);let label=isFact ? labels[i] : ordinary[j%ordinary.count]+" / revision \(j+1)";rows.append(Evidence(origin:t.governing,type:t,id:"\(i):\(j)",title:name+" "+label,date:clock.addingTimeInterval(-86400*Double(j+1)),dayOnly:true,source:t.rawValue,topics:[name],locator:"",importedAt:nil,via:"feed"))};let ts=Analysis.topics(rows,window:w,enabled:enabled);guard let topic=Search.rank(questions[i],topics:ts).first?.topic,topic.key==name.lowercased() else{fatalError("No topic for synthetic case")};let raw=rows.map{Dates.day($0.date)+" · "+$0.type.label+" · "+$0.title}.joined(separator:"\n");let request="Use only the supplied records. Answer in one sentence. State if the requested facts are missing; do not infer completion from a title.\n";let full=request+questions[i]+"\n"+raw;let compact=request+Export.simple(task:questions[i],topic:topic,window:w,coverage:[]);result.append(["id":name,"n":count,"full":full,"compact":compact,"recovery":"Additional dated titles for the same task:\n"+raw])};let data=try JSONSerialization.data(withJSONObject:result,options:[.prettyPrinted,.sortedKeys,.withoutEscapingSlashes]);FileHandle.standardOutput.write(data)}}
